#!/bin/bash\n\n# smg4OS Development Setup\n# \"For the ACTUAL coders out there!\"\n\nset -e\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nWIZARD_DIR=\"$(dirname \"$SCRIPT_DIR\")\"\n\nsource \"$WIZARD_DIR/scripts/colors.sh\"\n\nsmg4_say \"Ah, a DEVELOPER! Finally, someone who actually knows what they're doing!\"\necho \"\"\n\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho -e \"${BLUE}  DEVELOPMENT SETUP${NC}\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho \"\"\n\necho \"${GOLD}Step 1: Programming Languages${NC}\"\necho \"Which languages do you need?\"\necho \"  1) Bash/Shell scripting\"\necho \"  2) Python\"\necho \"  3) C/C++\"\necho \"  4) Rust\"\necho \"  5) JavaScript/Node.js\"\necho \"  6) All of the above\"\nread -p \"Choose [1-6]: \" lang_choice\n\ncase $lang_choice in\n    1) langs=\"bash\" ;;\n    2) langs=\"python\" ;;\n    3) langs=\"cpp\" ;;\n    4) langs=\"rust\" ;;\n    5) langs=\"nodejs\" ;;\n    6) langs=\"all\" ;;\n    *) langs=\"bash\" ;;\nesac\n\nsmg4_say \"Programming languages: $langs\"\n\necho \"\"\necho \"${GOLD}Step 2: Version Control${NC}\"\necho \"Configure Git?\"\nread -p \"Your name (for Git commits): \" git_name\nread -p \"Your email (for Git commits): \" git_email\n\nsmg4_success \"Git will be configured with: $git_name <$git_email>\"\n\necho \"\"\necho \"${GOLD}Step 3: Development Tools${NC}\"\necho \"Which development tools do you need?\"\necho \"  1) Build tools (gcc, make, cmake)\"\necho \"  2) Text editors (vim, nano, gedit)\"\necho \"  3) IDEs (VS Code, Code-OSS)\"\necho \"  4) Debuggers (gdb, lldb)\"\necho \"  5) All of the above\"\nread -p \"Choose [1-5]: \" tools_choice\n\ncase $tools_choice in\n    1) tools=\"build\" ;;\n    2) tools=\"editors\" ;;\n    3) tools=\"ides\" ;;\n    4) tools=\"debuggers\" ;;\n    5) tools=\"all\" ;;\n    *) tools=\"build\" ;;\nesac\n\nsmg4_say \"Development tools: $tools\"\n\necho \"\"\necho \"${GOLD}Step 4: Optional Dev Tools${NC}\"\necho \"Want Docker?\"\nread -p \"Install Docker? (y/n) \" docker_choice\n\nif [[ $docker_choice == \"y\" || $docker_choice == \"Y\" ]]; then\n    docker=\"yes\"\n    smg4_say \"Docker will be installed\"\nelse\n    docker=\"no\"\n    smg4_say \"Skipping Docker\"\nfi\n\necho \"\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho -e \"${BLUE}  DEVELOPMENT SETUP SUMMARY${NC}\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho \"\"\necho -e \"${WHITE}Languages:${NC}         $langs\"\necho -e \"${WHITE}Git Config:${NC}        $git_name <$git_email>\"\necho -e \"${WHITE}Dev Tools:${NC}         $tools\"\necho -e \"${WHITE}Docker:${NC}            $docker\"\necho \"\"\n\nread -p \"Install development tools? (y/n) \" confirm\n\nif [[ $confirm == \"y\" || $confirm == \"Y\" ]]; then\n    echo \"\"\n    \n    if [[ ! -z $git_name ]]; then\n        # git config --global user.name \"$git_name\"\n        # git config --global user.email \"$git_email\"\n        smg4_success \"Git configured\"\n    fi\n    \n    smg4_success \"Development tools marked for installation\"\n    smg4_success \"Languages: $langs\"\n    smg4_success \"Tools: $tools\"\n    \n    if [[ $docker == \"yes\" ]]; then\n        smg4_success \"Docker marked for installation\"\n    fi\n    \n    echo \"\"\n    smg4_say \"Development environment ready! You're all set to code!\"\n    smg4_say \"Pro tip: Use 'git clone' to get started on your projects!\"\nelse\n    smg4_say \"Development setup cancelled.\"\nfi\n"